SELECT sa.*, c.coursename, ci.classname, s.studentname, s.studentno, t.teachername
FROM student_attendance sa
LEFT JOIN course c ON sa.courseid = c.courseid
LEFT JOIN classinfo ci ON sa.classid = ci.classid
LEFT JOIN student s ON sa.studentid = s.studentid
LEFT JOIN teacher t ON sa.teacherid = t.teacherid

    AND sa.courseid = #{courseid}
    AND sa.classid = #{classid}
    AND sa.attenddate = #{attenddate}
    AND c.teacherid = #{courseTeacherId}

ORDER BY sa.attenddate DESC, s.studentno ASC
LIMIT #{offset}, #{limit}

